from PIL import Image
import numpy as np
for name in ['initial','observe20','ep19_35','ep19_45forward','ep19_50back','ep23_55p2','fail17']:
 fn=f'/app/output/{name}.jpg'
 try:a=np.asarray(Image.open(fn).convert('L'))
 except:continue
 m=(a>130)&(a<230)
 # only bottom area. components 8-connected via manual stack
 seen=np.zeros_like(m); comps=[]
 for y,x in zip(*np.where(m & ~seen)):
  if seen[y,x]:continue
  stack=[(y,x)];seen[y,x]=1;pts=[]
  while stack:
   yy,xx=stack.pop();pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=yy+dy,xx+dx
     if 170<=ny<245 and 115<=nx<240 and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;stack.append((ny,nx))
  if len(pts)>20:
   p=np.array(pts);cy,cx=p.mean(0);cov=np.cov(p[:,::-1].T);ev,V=np.linalg.eigh(cov);v=V[:,np.argmax(ev)];ang=np.degrees(np.arctan2(v[1],v[0]));comps.append((len(pts),round(cx,1),round(cy,1),round(ang,1),tuple(p.min(0)),tuple(p.max(0))))
 print('\n',name,sorted(comps,reverse=True)[:8])
